#!/usr/bin/env python3
"""Week 4 · harness for Task 3. Do not edit this file.

Both filters get exactly the same bits and the same items. Then we ask them
about a lot of things they have never seen.

    budget     80,000 bits  (10 KB)
    inserted   8,000 items
    queried    200,000 items that were never inserted
    scored     false positives
    required   zero false negatives, and memory within budget

    python3 bench.py
    python3 bench.py --yours
"""
import argparse

SEED, N_BITS, N_INSERT, N_QUERY = 246, 80_000, 8_000, 200_000


def build():
    inserted = [f"user:{i}@example.org" for i in range(N_INSERT)]
    absent = [f"ghost:{i}@example.org" for i in range(N_QUERY)]
    return inserted, absent


def run(cls, label, inserted, absent):
    f = cls(N_BITS, seed=SEED)
    for x in inserted:
        f.add(x)

    used = f.memory_bits()
    if used > N_BITS:
        raise RuntimeError(f"{label}: using {used:,} bits, budget is {N_BITS:,}")

    false_neg = sum(1 for x in inserted if x not in f)
    false_pos = sum(1 for x in absent if x in f)
    rate = false_pos / len(absent)
    print(f"  {label:<10} false positives {false_pos:>7,}  ({rate:>7.3%})   "
          f"false negatives {false_neg:>5}   bits {used:,}")
    return {"fp": false_pos, "rate": rate, "fn": false_neg}


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--yours", action="store_true")
    a = p.parse_args()

    inserted, absent = build()
    print(f"\n  {N_BITS:,} bits, {N_INSERT:,} items inserted, "
          f"{N_QUERY:,} queried\n")

    from task3_budget import NaiveFilter
    base = run(NaiveFilter, "baseline", inserted, absent)

    if a.yours:
        from task3_budget import YourFilter
        mine = run(YourFilter, "yours", inserted, absent)
        print()
        if mine["fn"] > 0:
            print(f"   FAIL  {mine['fn']} false negatives. The contract is that "
                  f"'no' means no.")
        else:
            cut = 1 - mine["rate"] / base["rate"] if base["rate"] else 0
            print(f"   ok    no false negatives")
            print(f"   false-positive rate cut by {cut:.1%}  "
                  f"({mine['rate']:.3%} from {base['rate']:.3%})")
            grade = ("strong" if mine["rate"] <= 0.009 else
                     "good" if cut >= 0.50 else
                     "pass" if cut > 0.05 else "not yet")
            print(f"\n   -> {grade}")
    print()


if __name__ == "__main__":
    main()
